import{_ as d,C as n,o as i,c as r,j as t,a,b as E,w as o,E as l,a8 as h,a7 as p}from"./chunks/framework.BCbKzsgW.js";const S=JSON.parse('{"title":"Cookie、Session 与设备管理","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/session.md","filePath":"development/common/authentication/session.md","lastUpdated":1793703140000}'),c={name:"development/common/authentication/session.md"};function A(k,e,u,C,B,g){const s=n("Mermaid");return i(),r("div",null,[e[1]||(e[1]=t("h1",{id:"cookiesession-yu-she-bei-guan-li",tabindex:"-1"},[a("Cookie、Session 与设备管理 "),t("a",{class:"header-anchor",href:"#cookiesession-yu-she-bei-guan-li","aria-label":'Permalink to "Cookie、Session 与设备管理"'},"​")],-1)),e[2]||(e[2]=t("p",null,"服务端 Session 让浏览器只持有一个随机会话凭据，账号、认证强度和撤销状态留在服务端。它适合自有网站，因为“当前设备退出”“撤销其他设备”“改密后重新登录”都能映射成服务端状态变化。",-1)),e[3]||(e[3]=t("h2",{id:"cookie-yu-fu-wu-duan-hui-hua-de-fen-gong",tabindex:"-1"},[a("Cookie 与服务端会话的分工 "),t("a",{class:"header-anchor",href:"#cookie-yu-fu-wu-duan-hui-hua-de-fen-gong","aria-label":'Permalink to "Cookie 与服务端会话的分工"'},"​")],-1)),e[4]||(e[4]=t("p",null,[a("浏览器接收 "),t("code",null,"Set-Cookie"),a(" 后，按域、路径、安全属性和上下文决定是否发送 Cookie。服务端收到 Cookie 再查询 Session；浏览器里存在一个 Cookie，并不说明对应会话仍有效。")],-1)),e[5]||(e[5]=t("p",null,"下图把首次建立会话与后续请求分开。只有全部认证因素完成后才签发正式会话，后续请求仍检查服务端状态。",-1)),(i(),E(h,null,{default:o(()=>[l(s,{id:"mermaid-15",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20C%20as%20%E6%B5%8F%E8%A7%88%E5%99%A8%0A%20%20%20%20participant%20A%20as%20%E5%BA%94%E7%94%A8%E5%90%8E%E7%AB%AF%0A%20%20%20%20participant%20S%20as%20%E4%BC%9A%E8%AF%9D%E4%B8%8E%E8%B4%A6%E5%8F%B7%E5%AD%98%E5%82%A8%0A%20%20%20%20C-%3E%3EA%3A%20%E6%8F%90%E4%BA%A4%E7%99%BB%E5%BD%95%E5%87%AD%E6%8D%AE%0A%20%20%20%20A-%3E%3EA%3A%20%E9%AA%8C%E8%AF%81%E5%87%AD%E6%8D%AE%E5%8F%8A%E6%89%80%E9%9C%80%20MFA%0A%20%20%20%20A-%3E%3ES%3A%20%E5%88%9B%E5%BB%BA%E6%96%B0%E4%BC%9A%E8%AF%9D%EF%BC%8C%E4%BF%9D%E5%AD%98%E5%87%AD%E6%8D%AE%E6%91%98%E8%A6%81%0A%20%20%20%20S--%3E%3EA%3A%20%E5%88%9B%E5%BB%BA%E6%88%90%E5%8A%9F%0A%20%20%20%20A--%3E%3EC%3A%20Set-Cookie%EF%BC%8C%E5%8F%91%E9%80%81%E9%9A%8F%E6%9C%BA%E4%BC%9A%E8%AF%9D%E5%87%AD%E6%8D%AE%0A%20%20%20%20C-%3E%3EA%3A%20%E4%B8%9A%E5%8A%A1%E8%AF%B7%E6%B1%82%E4%B8%8E%20Cookie%0A%20%20%20%20A-%3E%3ES%3A%20%E6%9F%A5%E8%AF%A2%E4%BC%9A%E8%AF%9D%E3%80%81%E8%B4%A6%E5%8F%B7%E4%B8%8E%E5%AE%89%E5%85%A8%E7%89%88%E6%9C%AC%0A%20%20%20%20S--%3E%3EA%3A%20%E5%BD%93%E5%89%8D%E7%8A%B6%E6%80%81%E4%B8%8E%E6%9C%9F%E9%99%90%0A%20%20%20%20alt%20%E5%B7%B2%E6%92%A4%E9%94%80%E3%80%81%E8%BF%87%E6%9C%9F%E6%88%96%E7%89%88%E6%9C%AC%E4%B8%8D%E5%8C%B9%E9%85%8D%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%8B%92%E7%BB%9D%E8%AE%A4%E8%AF%81%EF%BC%8C%E8%A6%81%E6%B1%82%E9%87%8D%E6%96%B0%E7%99%BB%E5%BD%95%0A%20%20%20%20else%20%E4%BC%9A%E8%AF%9D%E6%9C%89%E6%95%88%E4%B8%94%E8%B4%A6%E5%8F%B7%E5%8F%AF%E7%94%A8%0A%20%20%20%20%20%20%20%20A-%3E%3EA%3A%20%E7%BB%A7%E7%BB%AD%E6%A3%80%E6%9F%A5%E4%B8%9A%E5%8A%A1%E6%9D%83%E9%99%90%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%8C%89%E6%9D%83%E9%99%90%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%E6%88%96%E6%8B%92%E7%BB%9D%E8%AE%BF%E9%97%AE%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=p(`<p>存储不可用时进入受控故障路径，不按“会话有效”处理；缓存带来的状态延迟见后文。</p><p>下面是 HTTPS 站点的响应示意。<code>&lt;random-session-token&gt;</code> 需要替换为密码学安全随机数；示例的 8 小时只是 Cookie 保存时长，不代表推荐的通用会话策略。</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OK</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Set-Cookie</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> __Host-session=&lt;random-session-token&gt;; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=28800</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-store</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;authenticated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>根据 <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Set-Cookie" target="_blank" rel="noreferrer">MDN Set-Cookie</a>：</p><table tabindex="0"><thead><tr><th>属性</th><th>作用与边界</th></tr></thead><tbody><tr><td><code>Secure</code></td><td>限制 Cookie 经安全连接发送，不替代全站 HTTPS</td></tr><tr><td><code>HttpOnly</code></td><td>阻止脚本直接读取 Cookie；XSS 仍可能代用户发请求</td></tr><tr><td><code>SameSite=Lax</code></td><td>限制部分跨站携带行为，仍需独立 CSRF 防护</td></tr><tr><td><code>Path=/</code></td><td>控制发送路径，不能用作应用间安全隔离</td></tr><tr><td>不设置 <code>Domain</code></td><td>将 Cookie 限于当前主机</td></tr><tr><td><code>__Host-</code> 前缀</td><td>支持该前缀的浏览器要求 <code>Secure</code>、<code>Path=/</code> 且无 <code>Domain</code></td></tr><tr><td><code>Max-Age</code></td><td>浏览器保存上限，服务端必须独立检查失效条件</td></tr></tbody></table><p>跨源与跨站是不同概念。<code>app.example.com</code> 与 <code>api.example.com</code> 跨源，但在相同 scheme 等条件下可能同站；<code>SameSite</code> 无法替代对不可信同站子域的防护。</p><h2 id="hui-hua-ping-ju-yu-ji-lu" tabindex="-1">会话凭据与记录 <a class="header-anchor" href="#hui-hua-ping-ju-yu-ji-lu" aria-label="Permalink to &quot;会话凭据与记录&quot;">​</a></h2><p>会话凭据应不可预测，不编码邮箱、IP 或用户 ID。可使用 32 字节安全随机数，编码后放进 Cookie；这是设计选择。数据库保存其 SHA-256 摘要，以降低只读会话库泄露直接产生可用会话的风险。该处理适用于高熵随机凭据，不适用于低熵密码。</p><p>设备列表使用独立的非秘密 <code>session_id</code>，避免把 Cookie 中的凭据作为列表 ID 或日志字段。</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>session_id</code>、<code>token_digest</code></td><td>管理标识与凭据摘要</td></tr><tr><td><code>user_id</code>、<code>security_version</code></td><td>账号及创建时的安全版本</td></tr><tr><td><code>created_at</code>、<code>last_seen_at</code></td><td>创建与最近活动时间</td></tr><tr><td><code>idle_expires_at</code>、<code>absolute_expires_at</code></td><td>空闲与绝对过期边界</td></tr><tr><td><code>reauthenticated_at</code>、<code>auth_methods</code></td><td>近期认证与认证方式</td></tr><tr><td><code>revoked_at</code>、<code>revoke_reason</code></td><td>撤销状态与原因</td></tr><tr><td>设备描述、网络摘要</td><td>给用户识别设备，不能单独证明设备可信</td></tr></tbody></table><p>不要把 IP 或 User-Agent 固定匹配作为唯一有效性条件。移动网络和浏览器升级都会改变它们，攻击者也可能伪造；更适合用作风险信号。</p><h2 id="deng-lulun-huan-yu-guo-qi" tabindex="-1">登录、轮换与过期 <a class="header-anchor" href="#deng-lulun-huan-yu-guo-qi" aria-label="Permalink to &quot;登录、轮换与过期&quot;">​</a></h2><p>登录前的匿名会话与登录后的受信会话要轮换，防止会话固定攻击。权限提升、重要身份变化后也应重新评估是否轮换凭据。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#renew-the-session-id-after-any-privilege-level-change" target="_blank" rel="noreferrer">OWASP Session Management</a>给出了会话标识更新和服务端超时要求。</p><p>每次请求至少检查会话存在、未撤销、未超时、账号可用、安全版本匹配。滑动续期只能推进空闲期限，不能越过绝对期限；敏感操作还要检查近期认证。</p><p>记录活动时间不必每个请求都写库。可以按时间粒度合并写入，但须约定空闲时间的误差上限；缓存续期与数据库持久状态也要遵守相同的绝对上限。否则持续活跃的会话可能永不结束。</p><p>凭据轮换要考虑并发请求：旧凭据立即删除会使尚在途的请求失败，长时间双有效则扩大泄露窗口。可以选择接受短暂失败、限制性过渡或按会话版本串行更新，但要验证旧响应晚到时不能把浏览器覆盖回已失效凭据。</p><h2 id="duo-she-bei-tui-chu" tabindex="-1">多设备退出 <a class="header-anchor" href="#duo-she-bei-tui-chu" aria-label="Permalink to &quot;多设备退出&quot;">​</a></h2><p>“设备”通常只是产品展示单位，一个浏览器的两个 Profile 可能对应两个 Session；同一台机器也可能有多个账号会话。</p><table tabindex="0"><thead><tr><th>操作</th><th>服务端动作</th></tr></thead><tbody><tr><td>退出当前会话</td><td>撤销当前记录并清除 Cookie</td></tr><tr><td>退出指定设备</td><td>验证目标会话属于当前用户后撤销</td></tr><tr><td>退出其他设备</td><td>撤销同用户除当前实例外的记录</td></tr><tr><td>退出全部设备</td><td>更新安全版本或撤销所有会话，并清除当前 Cookie</td></tr><tr><td>修改密码或封禁</td><td>根据产品策略处理当前会话，同时撤销旧认证状态</td></tr></tbody></table><p>退出使用带 CSRF 防护的状态变更请求，避免 GET 链接产生退出副作用。清 Cookie 只是清理客户端持有物，不能替代服务端撤销。删除 Cookie 时使用相同名称、路径及域范围；<code>__Host-</code> Cookie 不设置 <code>Domain</code>。</p><p>“撤销成功”通常意味着后续通过认证检查的请求被拒绝，不能自动回滚此前已进入业务事务的操作。转账等敏感写入应在提交前检查必要状态，或使用业务侧的版本约束。</p><h2 id="huan-cun-yi-zhi-xing-yu-gu-zhang" tabindex="-1">缓存一致性与故障 <a class="header-anchor" href="#huan-cun-yi-zhi-xing-yu-gu-zhang" aria-label="Permalink to &quot;缓存一致性与故障&quot;">​</a></h2><p>如果服务 A 缓存 Session 30 秒，而服务 B 立即删除中心记录，A 仍可能接受旧会话。设计中应明确撤销生效的最坏时限：缓存剩余时间、事件传播和在途请求都可能贡献延迟。</p><p>按业务风险可以选择每次查询权威状态、短期缓存加可靠失效通知，或只在敏感写入重新查询。依赖不可用时，受保护操作不应降级成匿名放行；可返回明确的临时服务错误。是否允许已缓存状态继续支持低风险只读操作，需要独立的风险与时限策略。</p><p>若从旧备份恢复会话库，旧会话可能重新出现。恢复方案应验证撤销版本、全局失效代次与密钥状态，不能仅以“Redis 已恢复”作为完成条件。</p><h2 id="kua-yu-bu-shu-yu-deng-lu-hui-diao" tabindex="-1">跨域部署与登录回调 <a class="header-anchor" href="#kua-yu-bu-shu-yu-deng-lu-hui-diao" aria-label="Permalink to &quot;跨域部署与登录回调&quot;">​</a></h2><p>跨源 <code>fetch</code> 发送 Cookie 需要正确的凭据模式和服务端 CORS 配置；允许携带凭据时不能把允许来源设置成任意通配符，详见 <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS#requests_with_credentials" target="_blank" rel="noreferrer">MDN CORS</a>。CORS 控制浏览器能否向脚本暴露响应，不替代认证或 CSRF 防护。</p><p>OIDC 顶层 GET 回调通常更容易与 <code>SameSite=Lax</code> 配合；<code>form_post</code> 等跨站 POST 回调需要单独验证关联 Cookie 的发送行为。不要为修复回调丢状态而全站放宽 Cookie，或在丢失状态时跳过校验。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>MDN：<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Set-Cookie" target="_blank" rel="noreferrer">Set-Cookie</a></li><li>MDN：<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS#requests_with_credentials" target="_blank" rel="noreferrer">CORS — Requests with credentials</a></li><li>OWASP：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html" target="_blank" rel="noreferrer">Session Management Cheat Sheet</a></li></ul>`,30))])}const F=d(c,[["render",A]]);export{S as __pageData,F as default};
